      ['brass','brass',{color:0xb68e4e,roughness:.4,metalness:.78}],
      ['dark','dark',{color:0x202824,roughness:.8}],
      ['glass','glass',{color:0xd9e9e3,roughness:.06,transparent:true,opacity:.10,depthWrite:false}]
