    this.plate(1.03,.60,.065,.105,"shell",[0,1.30,.208],null,[.87,.44,.065]);
    this.plate(.88,.45,.016,.06,"rubber",[0,1.30,.203]);
    this.plate(.85,.42,.024,.055,"metal",[0,1.30,.230],null,[.79,.36,.035]);
