    this.pin(.085,.19,"joint",[elbow,.49,0],"z",16);
    this.pin(.045,.204,"metal",[elbow,.49,0],"z");
    this.plate(.12,.19,.12,.025,"yellow",[side*.58,.46,.08],[.55,0,-side*.3]);
    this.cable([[x,.80,-.08],[side*.56,.68,-.12],[side*.58,.5,-.06]],.018,"copper");
