    const envelope=Math.sin(Math.PI*progress)**2;
    switch(this.gesture) {
      case "mission": case "multiplier":
        left.rotation.z=-1.05*envelope;
        left.rotation.x=.28*envelope*Math.sin(progress*Math.PI*6);
        right.rotation.z=.4*envelope;
